import zlib, subprocess
big = b"A"*200000 + b"B"*200000
def chunked_with_dict(data, blocksize=128*1024, level=6):
    out = b""
    prev = b""
    for i in range(0, len(data), blocksize):
        chunk = data[i:i+blocksize]
        zdict = prev[-32768:] if prev else None
        if zdict is not None:
            c = zlib.compressobj(level, zlib.DEFLATED, -15, 8, zlib.Z_DEFAULT_STRATEGY, zdict)
        else:
            c = zlib.compressobj(level, zlib.DEFLATED, -15)
        out += c.compress(chunk)
        if i+blocksize < len(data):
            out += c.flush(zlib.Z_SYNC_FLUSH)
        else:
            out += c.flush()
        prev = chunk
    return out

for bs in [128*1024]:
    try:
        raw = chunked_with_dict(big, bs)
        print(f"bs={bs} len={len(raw)}")
        p=subprocess.run(["/workspace/executable","-b",str(bs//1024)], input=big, capture_output=True)
        pigz_raw = p.stdout[10:-8]
        print(f"  pigz len={len(pigz_raw)} match={raw==pigz_raw}")
        if raw!=pigz_raw:
            print(f"  our {raw[:80].hex()}")
