/* pigz clone - parallel gzip implementation (single-threaded compatible version)
 * Original implementation based on behavioral observation.
 * Version 2.8 compatible.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <dirent.h>
#include <utime.h>
#include <time.h>
#include <zlib.h>
#include <stdint.h>
#include <ctype.h>
#include <limits.h>
#include <libgen.h>

#define VERSION "2.8"
#define ZLIB_VERSION_STR "1.2.11"

static char *progname = NULL;
static int opt_quiet = 0;
static int opt_verbose = 0;
static int opt_level = 6;
static char *opt_alias = NULL;
static long opt_blocksize = 128;
static int opt_to_stdout = 0;
static char *opt_comment = NULL;
static int opt_decompress = 0; /* set by -d */
static int opt_force = 0;
static int opt_first = 0;
static int opt_huffman = 0;
static int opt_independent = 0;
static unsigned long long opt_iterations = 15;
static unsigned long long opt_maxsplits = 15;
static int opt_keep = 0;
static int opt_format = 0; /* 0 gzip, 1 zlib, 2 zip */
static char *opt_suffix = NULL; /* custom, NULL means default based on format */
static int opt_list = 0;
static int opt_test = 0;
static int opt_recursive = 0;
static int opt_rsyncable = 0;
static int opt_oneblock = 0;
static int opt_synchronous = 0;
static int opt_rle = 0;
static unsigned long long opt_processes = 0; /* 0 means default */
static int is_unpigz = 0;

/* store name/time ops in order */
#define MAX_STORE_OPS 1024
static char store_ops[MAX_STORE_OPS];
static int store_ops_count = 0;

/* order tracking for test vs decompress: last wins */
static int last_test_decomp = 0; /* 0 none, 1 decompress, 2 test */

/* for -h/-V/-L immediate handling, need to know if quiet/verbose set before */
static void print_help(void);
static void print_version(int verbose);
static void print_license(void);

static void msg_abort(const char *fmt, const char *arg) {
    if (opt_quiet) return;
    if (arg)
        fprintf(stderr, "%s: abort: ", progname);
    else
        fprintf(stderr, "%s: abort: ", progname);
    if (arg) {
        /* fmt contains %s */
        fprintf(stderr, fmt, arg);
    } else {
        fprintf(stderr, "%s", fmt);
    }
    fprintf(stderr, "\n");
}

static void msg_abort_str(const char *s) {
    if (opt_quiet) return;
    fprintf(stderr, "%s: abort: %s\n", progname, s);
}

static void msg_skipping(const char *name, const char *reason) {
    if (opt_quiet) return;
    if (reason)
        fprintf(stderr, "%s: skipping: %s %s\n", progname, name, reason);
    else
        fprintf(stderr, "%s: skipping: %s\n", progname, name);
}

static void msg_skipping2(const char *name, const char *reason) {
    /* for "name: reason" style: skipping: <stdin>: corrupted ... */
    if (opt_quiet) return;
    fprintf(stderr, "%s: skipping: %s: %s\n", progname, name, reason);
}

static void msg_warning(const char *name, const char *reason) {
    if (opt_quiet) return;
    fprintf(stderr, "%s: warning: %s: %s\n", progname, name, reason);
}

static void msg_verbose(const char *from, const char *to) {
    if (opt_quiet) return;
    if (!opt_verbose) return;
    fprintf(stderr, "%s to %s \n", from, to);
}

/* basename */
static char *my_basename(char *path) {
    char *b = strrchr(path, '/');
    if (b) return b+1;
    return path;
}

static void print_help(void) {
    if (opt_quiet) return;
    fprintf(stderr, "Usage: pigz [options] [files ...]\n");
    fprintf(stderr, "  will compress files in place, adding the suffix '.gz'. If no files are\n");
    fprintf(stderr, "  specified, stdin will be compressed to stdout. pigz does what gzip does,\n");
    fprintf(stderr, "  but spreads the work over multiple processors and cores when compressing.\n");
    fprintf(stderr, "\nOptions:\n");
    fprintf(stderr, "  -0 to -9, -11        Compression level (level 11, zopfli, is much slower)\n");
    fprintf(stderr, "  --fast, --best       Compression levels 1 and 9 respectively\n");
    fprintf(stderr, "  -A, --alias xxx      Use xxx as the name for any --zip entry from stdin\n");
    fprintf(stderr, "  -b, --blocksize mmm  Set compression block size to mmmK (default 128K)\n");
    fprintf(stderr, "  -c, --stdout         Write all processed output to stdout (won't delete)\n");
    fprintf(stderr, "  -C, --comment ccc    Put comment ccc in the gzip or zip header\n");
    fprintf(stderr, "  -d, --decompress     Decompress the compressed input\n");
    fprintf(stderr, "  -f, --force          Force overwrite, compress .gz, links, and to terminal\n");
    fprintf(stderr, "  -F  --first          Do iterations first, before block split for -11\n");
    fprintf(stderr, "  -h, --help           Display a help screen and quit\n");
    fprintf(stderr, "  -H, --huffman        Use only Huffman coding for compression\n");
    fprintf(stderr, "  -i, --independent    Compress blocks independently for damage recovery\n");
    fprintf(stderr, "  -I, --iterations n   Number of iterations for -11 optimization\n");
    fprintf(stderr, "  -J, --maxsplits n    Maximum number of split blocks for -11\n");
    fprintf(stderr, "  -k, --keep           Do not delete original file after processing\n");
    fprintf(stderr, "  -K, --zip            Compress to PKWare zip (.zip) single entry format\n");
    fprintf(stderr, "  -l, --list           List the contents of the compressed input\n");
    fprintf(stderr, "  -L, --license        Display the pigz license and quit\n");
    fprintf(stderr, "  -m, --no-time        Do not store or restore mod time\n");
    fprintf(stderr, "  -M, --time           Store or restore mod time\n");
    fprintf(stderr, "  -n, --no-name        Do not store or restore file name or mod time\n");
    fprintf(stderr, "  -N, --name           Store or restore file name and mod time\n");
    fprintf(stderr, "  -O  --oneblock       Do not split into smaller blocks for -11\n");
    fprintf(stderr, "  -p, --processes n    Allow up to n compression threads (default is the\n");
    fprintf(stderr, "                       number of online processors, or 8 if unknown)\n");
    fprintf(stderr, "  -q, --quiet          Print no messages, even on error\n");
    fprintf(stderr, "  -r, --recursive      Process the contents of all subdirectories\n");
    fprintf(stderr, "  -R, --rsyncable      Input-determined block locations for rsync\n");
    fprintf(stderr, "  -S, --suffix .sss    Use suffix .sss instead of .gz (for compression)\n");
    fprintf(stderr, "  -t, --test           Test the integrity of the compressed input\n");
    fprintf(stderr, "  -U, --rle            Use run-length encoding for compression\n");
    fprintf(stderr, "  -v, --verbose        Provide more verbose output\n");
    fprintf(stderr, "  -V  --version        Show the version of pigz\n");
    fprintf(stderr, "  -Y  --synchronous    Force output file write to permanent storage\n");
    fprintf(stderr, "  -z, --zlib           Compress to zlib (.zz) instead of gzip format\n");
    fprintf(stderr, "  --                   All arguments after \"--\" are treated as files\n");
}

static void print_version(int verbose) {
    printf("pigz %s\n", VERSION);
    if (verbose) {
        printf("zlib %s\n", ZLIB_VERSION_STR);
    }
    fflush(stdout);
}

static void print_license(void) {
    printf("pigz %s\n", VERSION);
    printf("Copyright (C) 2007-2023 Mark Adler\n");
    printf("Subject to the terms of the zlib license.\n");
    printf("No warranty is provided or implied.\n");
    fflush(stdout);
}

/* numeric parsing: returns 0 on success, -1 invalid numeric, -2 empty, -3 overflow */
static int parse_ull(const char *s, unsigned long long *out) {
    if (s == NULL || *s == '\0') return -2;
    /* must be all digits */
    for (const char *p = s; *p; p++) {
        if (*p < '0' || *p > '9') return -1;
    }
    errno = 0;
    char *end;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno == ERANGE) return -1;
    if (*end != '\0') return -1;
    *out = v;
    return 0;
}

CEOF
cat pigz.c | head -n 50
