static int parse_short_arg(const char *arg, char ***argv_ptr, int *argc_ptr) {
    int i=1;
    int len=strlen(arg);
    while (i<len) {
        char c=arg[i];
        if (c>='0' && c<='9') {
            int j=i;
            while (j<len && arg[j]>='0' && arg[j]<='9') j++;
            int nlen=j-i;
            char numbuf[128];
            if (nlen>= (int)sizeof(numbuf)) nlen=sizeof(numbuf)-1;
            memcpy(numbuf, arg+i, nlen);
            numbuf[nlen]='\0';
            /* parse value, check overflow */
            unsigned long long v=0;
            int overflow=0;
            for (int k=0;k<nlen;k++) {
                int d=numbuf[k]-'0';
                if (v > (18446744073709551615ULL - (unsigned long long)d)/10) { overflow=1; break; }
                v=v*10+(unsigned long long)d;
            }
            if (overflow || v>11 || v==10) {
                if (!opt_quiet) fprintf(stderr, "%s: abort: only levels 0..9 and 11 are allowed\n", progname);
                return 22;
            }
            opt_level=(int)v;
            i=j;
            continue;
        } else if (c=='b'||c=='p'||c=='I'||c=='J'||c=='A') {
            const char *rest=arg+i+1;
            int has_rest=(rest[0]!='\0');
            int r=handle_short_single(c, rest, has_rest, argv_ptr, argc_ptr);
            if (r) return r;
            break;
        } else if (c=='S'||c=='C') {
            const char *rest=arg+i+1;
            int has_rest=(rest[0]!='\0');
            int r=handle_short_single(c, rest, has_rest, argv_ptr, argc_ptr);
            if (r) return r;
            break;
        } else if (c=='h'||c=='V'||c=='L') {
            int r=handle_short_single(c, "", 0, argv_ptr, argc_ptr);
            if (r==1) return 1;
            if (r==22) return 22;
            /* r==0 means h suppressed by quiet, continue with rest */
            i++;
            continue;
        } else {
            int r=handle_short_single(c, "", 0, argv_ptr, argc_ptr);
            if (r) return r;
            i++;
            continue;
        }
