/* parse args: argc/argv (argv[0] is first arg after progname, argc is count) */
/* is_env: 1 for env, 0 for cmdline. For env, files not allowed, "--" invalid, "-" files error. */
/* For cmdline, collect files. */
/* Returns 0 success, 22 error, 1 quit (help/version/license, exit 0) */
static int parse_arg_list(int argc, char **argv, int is_env, const char *envname, char ***out_files, int *out_nfiles) {
    /* out_files only for cmdline; for env, should be NULL */
    int dashdash=0;
    /* for cmdline, allocate files */
    char **files=NULL;
    int nfiles=0, cap=0;
    if (!is_env) {
        cap=16; files=malloc(cap*sizeof(char*));
    }
    /* need to iterate with index that can be advanced when consuming next arg for params */
    /* Use pointer and remaining count */
    char **pp=argv;
    int rem=argc;
    while (rem>0) {
        char *arg=pp[0];
        if (is_env) {
            /* env: arg starting with '-'? If not, files error. If "--", invalid option (not separator). If "-" alone, files error. */
            if (arg[0]!='-') {
                if (!opt_quiet) fprintf(stderr, "%s: abort: cannot provide files in %s environment variable\n", progname, envname);
                if (!is_env) { for(int i=0;i<nfiles;i++) free(files[i]); free(files); }
                return 22;
            }
            if (strcmp(arg,"-")==0) {
                if (!opt_quiet) fprintf(stderr, "%s: abort: cannot provide files in %s environment variable\n", progname, envname);
                return 22;
            }
            if (strcmp(arg,"--")==0) {
                /* treat as invalid option, not separator */
                if (!opt_quiet) fprintf(stderr, "%s: abort: invalid option: --\n", progname);
                return 22;
            }
            if (arg[0]=='-' && arg[1]=='-') {
                /* long */
                int r=handle_long_option(arg, &pp, &rem);
                if (r==1) return 1;
                if (r==22) return 22;
                /* advance */
                pp++; rem--;
                continue;
            } else {
                /* short */
                int r=parse_short_arg(arg, &pp, &rem);
                if (r==1) return 1;
                if (r==22) return 22;
                pp++; rem--;
                continue;
            }
        } else {
            /* cmdline */
            if (dashdash) {
                /* all remaining are files, even starting with - */
                if (nfiles>=cap){cap*=2;files=realloc(files,cap*sizeof(char*));}
                files[nfiles++]=strdup(arg);
                pp++; rem--;
                continue;
            }
            if (strcmp(arg,"--")==0) {
                dashdash=1;
                pp++; rem--;
                continue;
            }
            if (strcmp(arg,"-")==0) {
                /* stdin file */
                if (nfiles>=cap){cap*=2;files=realloc(files,cap*sizeof(char*));}
                files[nfiles++]=strdup(arg);
                pp++; rem--;
                continue;
            }
            if (arg[0]!='-') {
                /* file */
                if (nfiles>=cap){cap*=2;files=realloc(files,cap*sizeof(char*));}
                files[nfiles++]=strdup(arg);
                pp++; rem--;
                continue;
            }
            /* starts with '-', could be option or file like "-foo" without --? Actually "-foo" is parsed as options, not file. Only after "--" are dash files treated as files. Good. */
            /* Check if arg is exactly "-" (already handled) or "--" (handled). Now arg starts with '-' and len>=2, second char maybe '-' for long, else short. */
            if (arg[0]=='-' && arg[1]=='-') {
                int r=handle_long_option(arg, &pp, &rem);
                if (r==1) {
                    /* quit, ignore remaining? For -h/-V/-L, ignore files? Yes, quit immediately. */
                    for(int i=0;i<nfiles;i++) free(files[i]); free(files);
                    *out_files=NULL; *out_nfiles=0;
                    return 1;
                }
                if (r==22) {
                    for(int i=0;i<nfiles;i++) free(files[i]); free(files);
                    return 22;
                }
                pp++; rem--;
                continue;
            } else {
                /* short arg, could be like "-"?? Already handled. So len>=2. */
                int r=parse_short_arg(arg, &pp, &rem);
                if (r==1) {
                    for(int i=0;i<nfiles;i++) free(files[i]); free(files);
                    *out_files=NULL; *out_nfiles=0;
                    return 1;
                }
                if (r==22) {
                    for(int i=0;i<nfiles;i++) free(files[i]); free(files);
                    return 22;
                }
                pp++; rem--;
                continue;
            }
        }
    }
    if (!is_env) {
        *out_files=files;
        *out_nfiles=nfiles;
    }
    return 0;
}

