    /* simple: read all, compress with zlib, write header/trailer */
    /* Use level, etc. */
    size_t cap=8192, len=0;
    unsigned char *data=malloc(cap);
    size_t n;
    while ((n=fread(data+len,1,cap-len,stdin))>0) {
        len+=n;
        if (len==cap) { cap*=2; data=realloc(data,cap); }
        if (feof(stdin)) break;
        if (ferror(stdin)) break;
    }
