    /* We'll use a loop */
    unsigned char *outbuf=malloc(8192);
    size_t outbuf_cap=8192, outbuf_len=0;
    strm.next_out=outbuf; strm.avail_out=outbuf_cap;
    int flush=Z_FINISH;
    while (1) {
        int r=deflate(&strm, flush);
        size_t have=outbuf_cap-strm.avail_out;
        /* append to final? Actually we need to grow */
        if (r==Z_STREAM_END) {
            outbuf_len=have;
            break;
        }
        if (r!=Z_OK) { deflateEnd(&strm); free(data); free(outbuf); free(out); return 1; }
        if (strm.avail_out==0) {
            size_t newcap=outbuf_cap*2;
            unsigned char *nb=realloc(outbuf,newcap);
            strm.next_out=nb+outbuf_cap;
            strm.avail_out=newcap-outbuf_cap;
            outbuf=nb; outbuf_cap=newcap;
        }
    }
    outbuf_len=outbuf_cap-strm.avail_out;
    deflateEnd(&strm);
    /* write gzip header/trailer or zlib/zip? For now only gzip */
    if (opt_format==1) {
