        }
        fwrite(outbuf,1,outbuf_len,stdout);
        uLong crc=crc32(0L,Z_NULL,0);
        crc=crc32(crc,data,len);
        uint32_t isize=(uint32_t)(len & 0xffffffff);
        fputc(crc&0xFF,stdout); fputc((crc>>8)&0xFF,stdout); fputc((crc>>16)&0xFF,stdout); fputc((crc>>24)&0xFF,stdout);
