/* ===== compression ===== */
static int deflate_memory(unsigned char *in, size_t inlen, unsigned char **out, size_t *outlen) {
    int level = opt_level==11?9:opt_level;
    int strategy=Z_DEFAULT_STRATEGY;
    if (opt_huffman) strategy=Z_HUFFMAN_ONLY;
    else if (opt_rle) strategy=Z_RLE;
    z_stream strm;
    memset(&strm,0,sizeof(strm));
    if (deflateInit2(&strm, level, Z_DEFLATED, -15, 8, strategy)!=Z_OK) return -1;
    size_t cap=inlen+1024;
    if (cap<8192) cap=8192;
    unsigned char *buf=malloc(cap);
    strm.next_in=in;
    strm.avail_in=inlen;
    strm.next_out=buf;
    strm.avail_out=cap;
    while (1) {
        int r=deflate(&strm, Z_FINISH);
        if (r==Z_STREAM_END) break;
        if (r!=Z_OK) { deflateEnd(&strm); free(buf); return -1; }
        if (strm.avail_out==0) {
            size_t used=cap;
            size_t newcap=cap*2;
            unsigned char *nb=realloc(buf,newcap);
            strm.next_out=nb+used;
            strm.avail_out=newcap-used;
            buf=nb; cap=newcap;
        }
    }
    size_t len2=cap-strm.avail_out;
    deflateEnd(&strm);
    *out=buf;
    *outlen=len2;
    return 0;
}

/* DOS time conversion */
static void unix_to_dos(time_t t, uint16_t *dos_time, uint16_t *dos_date) {
    struct tm *tm=localtime(&t);
    if (!tm) { *dos_time=0; *dos_date=0; return; }
    int year=tm->tm_year+1900;
    if (year<1980) { *dos_time=0; *dos_date=0; return; }
    if (year>2107) { year=2107; } /* clamp? DOS max 2107 */
    *dos_date = ((year-1980)<<9)|( (tm->tm_mon+1)<<5)|(tm->tm_mday);
    *dos_time = (tm->tm_hour<<11)|(tm->tm_min<<5)|(tm->tm_sec/2);
}

/* compress to gzip memory: filename may be NULL (no fname), mtime_raw 0 if no time, comment may be NULL */
static int compress_gzip(unsigned char *in, size_t inlen, const char *fname, uint32_t mtime, const char *comment, unsigned char **out, size_t *outlen) {
    unsigned char *def=NULL; size_t deflen=0;
    if (deflate_memory(in,inlen,&def,&deflen)!=0) return -1;
    size_t hdr_len=10;
    size_t fname_len=fname?strlen(fname)+1:0;
    size_t comment_len=comment?strlen(comment)+1:0;
    size_t total=hdr_len+fname_len+comment_len+deflen+8;
    unsigned char *buf=malloc(total);
    buf[0]=0x1f; buf[1]=0x8b; buf[2]=8;
    int flg=0;
    if (fname) flg|=0x08;
    if (comment) flg|=0x10;
    buf[3]=flg;
    buf[4]=mtime&0xFF; buf[5]=(mtime>>8)&0xFF; buf[6]=(mtime>>16)&0xFF; buf[7]=(mtime>>24)&0xFF;
    int xfl=0;
    if (opt_level==1) xfl=4;
    else if (opt_level==9 || opt_level==11) xfl=2;
    buf[8]=xfl; buf[9]=3;
    size_t pos=10;
    if (fname) { memcpy(buf+pos,fname,fname_len); pos+=fname_len; }
    if (comment) { memcpy(buf+pos,comment,comment_len); pos+=comment_len; }
    memcpy(buf+pos,def,deflen); pos+=deflen;
    free(def);
    uint32_t crc=crc32(0L,Z_NULL,0);
    crc=crc32(crc,in,inlen);
