    buf[pos++]=crc&0xFF; buf[pos++]=(crc>>8)&0xFF; buf[pos++]=(crc>>16)&0xFF; buf[pos++]=(crc>>24)&0xFF;
    buf[pos++]=isize&0xFF; buf[pos++]=(isize>>8)&0xFF; buf[pos++]=(isize>>16)&0xFF; buf[pos++]=(isize>>24)&0xFF;
    *out=buf; *outlen=total;
    return 0;
