static int compress_zlib(unsigned char *in, size_t inlen, unsigned char **out, size_t *outlen) {
    unsigned char *def=NULL; size_t deflen=0;
    if (deflate_memory(in,inlen,&def,&deflen)!=0) return -1;
    size_t total=2+deflen+4;
    unsigned char *buf=malloc(total);
    unsigned char h0=0x78,h1=0x9c;
    if (opt_level==0) { h0=0x78; h1=0x9c; }
    else if (opt_level==1) { h0=0x78; h1=0x01; }
    else if (opt_level>=2 && opt_level<=5) { h0=0x78; h1=0x9c; }
    else if (opt_level>=6 && opt_level<=8) { h0=0x78; h1=0x5e; }
    else if (opt_level==9 || opt_level==11) { h0=0x78; h1=0xda; }
    buf[0]=h0; buf[1]=h1;
    memcpy(buf+2,def,deflen);
    free(def);
    uint32_t adler=adler32(0L,Z_NULL,0);
    adler=adler32(adler,in,inlen);
    buf[2+deflen]=(adler>>24)&0xFF; buf[2+deflen+1]=(adler>>16)&0xFF; buf[2+deflen+2]=(adler>>8)&0xFF; buf[2+deflen+3]=adler&0xFF;
    *out=buf; *outlen=total;
    return 0;
}

static int compress_zip(unsigned char *in, size_t inlen, const char *fname, uint32_t ut_mtime, uint16_t dos_time, uint16_t dos_date, const char *comment, unsigned char **out, size_t *outlen) {
    unsigned char *def=NULL; size_t deflen=0;
    if (deflate_memory(in,inlen,&def,&deflen)!=0) return -1;
    uint32_t crc=crc32(0L,Z_NULL,0);
    crc=crc32(crc,in,inlen);
    size_t fnlen=strlen(fname);
    size_t comment_len=comment?strlen(comment):0;
