    buf[pos++]=0xFF; buf[pos++]=0xFF; buf[pos++]=0xFF; buf[pos++]=0xFF; /* comp FFFFFFFF */
    buf[pos++]=0xFF; buf[pos++]=0xFF; buf[pos++]=0xFF; buf[pos++]=0xFF; /* uncomp FFFFFFFF */
