    buf[pos++]=0x2d; buf[pos++]=0xFF; /* ver made? Observed FF2D? Actually vermade FF2D (bytes 2D FF? Little-endian? Our earlier parse vermade FF2D means bytes 2D FF? Let's check: central bytes after sig: 2D FF 2D 00 ... That's vermade 0xFF2D? Bytes 2D FF? Little-endian 0xFF2D = bytes 2D FF. Good. So first two bytes after sig are 2D FF. */
    /* Wait our earlier central hex: 504B01022DFF2D00... After PK0102 (4), next 2 are 2DFF? Actually hex "504B01022DFF2D00" => after sig, bytes 2D FF 2D 00. That's vermade 0xFF2D (2D FF), verneed 0x002D (2D 00). Good. So vermade low 2D, high FF. */
    /* Our code above wrote 0x2D,0xFF for vermade? We wrote buf[pos++]=0x2D; buf[pos++]=0xFF; Good. Next verneed 0x2D,0x00. */
    buf[pos++]=0x2d; buf[pos++]=0x00; /* ver need 45 */
    buf[pos++]=0x08; buf[pos++]=0x00; /* flag */
    buf[pos++]=0x08; buf[pos++]=0x00; /* method */
    buf[pos++]=dos_time&0xFF; buf[pos++]=(dos_time>>8)&0xFF;
    buf[pos++]=dos_date&0xFF; buf[pos++]=(dos_date>>8)&0xFF;
    buf[pos++]=crc&0xFF; buf[pos++]=(crc>>8)&0xFF; buf[pos++]=(crc>>16)&0xFF; buf[pos++]=(crc>>24)&0xFF;
    /* Use 32-bit sizes in central (truncate? For large >4G, need zip64? But our files <4G, so truncate to 32. Pigz uses 32-bit in central even for large? For now, truncate. */
    uint32_t c32=(uint32_t)(c64 & 0xffffffff);
    uint32_t u32=(uint32_t)(u64 & 0xffffffff);
    buf[pos++]=c32&0xFF; buf[pos++]=(c32>>8)&0xFF; buf[pos++]=(c32>>16)&0xFF; buf[pos++]=(c32>>24)&0xFF;
    buf[pos++]=u32&0xFF; buf[pos++]=(u32>>8)&0xFF; buf[pos++]=(u32>>16)&0xFF; buf[pos++]=(u32>>24)&0xFF;
    buf[pos++]=fnlen&0xFF; buf[pos++]=(fnlen>>8)&0xFF;
    buf[pos++]=central_extra&0xFF; buf[pos++]=(central_extra>>8)&0xFF;
    buf[pos++]=comment_len&0xFF; buf[pos++]=(comment_len>>8)&0xFF;
    buf[pos++]=0; buf[pos++]=0; /* disk */
    buf[pos++]=0; buf[pos++]=0; /* int attr */
    buf[pos++]=0; buf[pos++]=0; buf[pos++]=0; buf[pos++]=0; /* ext attr */
    buf[pos++]=0; buf[pos++]=0; buf[pos++]=0; buf[pos++]=0; /* offset (0, since single entry at 0) */
    memcpy(buf+pos,fname,fnlen); pos+=fnlen;
