    buf[pos++]=0x55; buf[pos++]=0x54; buf[pos++]=0x05; buf[pos++]=0x00; buf[pos++]=0x01;
    buf[pos++]=ut_mtime&0xFF; buf[pos++]=(ut_mtime>>8)&0xFF; buf[pos++]=(ut_mtime>>16)&0xFF; buf[pos++]=(ut_mtime>>24)&0xFF;
    if (comment_len) { memcpy(buf+pos,comment,comment_len); pos+=comment_len; }
    /* EOCD */
    buf[pos++]=0x50; buf[pos++]=0x4B; buf[pos++]=0x05; buf[pos++]=0x06;
    buf[pos++]=0; buf[pos++]=0; /* disk1 */
    buf[pos++]=0; buf[pos++]=0; /* disk2 */
    buf[pos++]=1; buf[pos++]=0; /* entries1 */
    buf[pos++]=1; buf[pos++]=0; /* entries2 */
    uint32_t csize=(uint32_t)central_len;
    uint32_t coff=(uint32_t)central_offset;
    buf[pos++]=csize&0xFF; buf[pos++]=(csize>>8)&0xFF; buf[pos++]=(csize>>16)&0xFF; buf[pos++]=(csize>>24)&0xFF;
    buf[pos++]=coff&0xFF; buf[pos++]=(coff>>8)&0xFF; buf[pos++]=(coff>>16)&0xFF; buf[pos++]=(coff>>24)&0xFF;
    buf[pos++]=0; buf[pos++]=0; /* comment len */
    *out=buf; *outlen=total;
    return 0;
}

